"use client"
import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Card } from "@/components/ui/card";
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useRouter } from "next/navigation";

const patientsData = [
  {
    id: 1,
    name: "John Doe",
    avatar: null,
    lastConsultation: "2024-06-10",
    visits: 5,
  },
  {
    id: 2,
    name: "Jane Smith",
    avatar: null,
    lastConsultation: "2024-06-08",
    visits: 2,
  },
  {
    id: 3,
    name: "Alice Brown",
    avatar: null,
    lastConsultation: "2024-06-01",
    visits: 8,
  },
  {
    id: 4,
    name: "Bob Lee",
    avatar: null,
    lastConsultation: "2024-05-28",
    visits: 1,
  },
];

const sortOptions = [
  { value: "newest", label: "Newest" },
  { value: "oldest", label: "Oldest" },
  { value: "most", label: "Most Visits" },
];

function sortPatients(patients, sort) {
  if (sort === "newest") {
    return [...patients].sort((a, b) => new Date(b.lastConsultation) - new Date(a.lastConsultation));
  }
  if (sort === "oldest") {
    return [...patients].sort((a, b) => new Date(a.lastConsultation) - new Date(b.lastConsultation));
  }
  if (sort === "most") {
    return [...patients].sort((a, b) => b.visits - a.visits);
  }
  return patients;
}

function PatientCard({ patient }) {
    const router = useRouter();
  return (
    <Card className="shadow hover:shadow-lg transition rounded-xl p-4 flex flex-col items-center gap-2">
      <Avatar name={patient.name} src={patient.avatar} className="w-16 h-16" />
      <div className="font-semibold text-center">{patient.name}</div>
      <Badge variant="outline" className="mb-2">Last: {patient.lastConsultation}</Badge>
      <Button size="sm" className="rounded-lg w-full" onClick={() =>{router.push('/doctor/patients/history')}}>View Profile</Button>
    </Card>
  );
}

export default function PatientsPage() {
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("newest");

  const filtered = sortPatients(
    patientsData.filter((p) => p.name.toLowerCase().includes(search.toLowerCase())),
    sort
  );

  return (
    <div className="max-w-5xl mx-auto py-8">
      <h1 className="text-2xl font-bold mb-6">My Patients</h1>
      <div className="flex flex-col sm:flex-row gap-4 mb-6 items-center">
        <Input
          placeholder="Search by name..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="max-w-xs rounded-xl"
        />
        <div className="ml-auto flex items-center gap-2">
          <label htmlFor="sort" className="text-sm text-gray-500">Sort by:</label>
          <select
            id="sort"
            value={sort}
            onChange={(e) => setSort(e.target.value)}
            className="rounded-lg border-gray-300 text-sm px-2 py-1"
          >
            {sortOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {filtered.length ? filtered.map((patient) => (
          <PatientCard key={patient.id} patient={patient} />
        )) : <div className="col-span-full text-center text-gray-400">No patients found.</div>}
      </div>
    </div>
  );
} 